from pysat.solvers import Glucose4
from pysat.card import CardEnc, EncType
import time

def solve():
    # 15 vertices, labels 0..40
    # 40 edges, differences 1..40

    edges = []
    for g in range(3):
        for i in range(5):
            for j in range(i + 1, 5):
                edges.append((g * 5 + i, g * 5 + j))
    for g in range(2):
        for i in range(5):
            edges.append((g * 5 + i, (g + 1) * 5 + i))

    V = 15
    L = 41
    E = 40

    # x[v][l] = v * L + l + 1
    def x(v, l):
        return v * L + l + 1

    # y[e][d] = V * L + e * E + d
    def y(e, d):
        return V * L + e * E + d

    solver = Glucose4()

    # Each vertex has exactly one label
    for v in range(V):
        solver.add_clause([x(v, l) for l in range(L)])
        for l1 in range(L):
            for l2 in range(l1 + 1, L):
                solver.add_clause([-x(v, l1), -x(v, l2)])

    # Each label is used at most once
    for l in range(L):
        for v1 in range(V):
            for v2 in range(v1 + 1, V):
                solver.add_clause([-x(v1, l), -x(v2, l)])

    # Each edge has exactly one difference
    for e in range(E):
        solver.add_clause([y(e, d) for d in range(1, L)])
        for d1 in range(1, L):
            for d2 in range(d1 + 1, L):
                solver.add_clause([-y(e, d1), -y(e, d2)])

    # Each difference is used exactly once (since E = L - 1 = 40)
    for d in range(1, L):
        solver.add_clause([y(e, d) for e in range(E)])
        for e1 in range(E):
            for e2 in range(e1 + 1, E):
                solver.add_clause([-y(e1, d), -y(e2, d)])

    # Link x and y
    for e_idx, (u, v) in enumerate(edges):
        for l1 in range(L):
            for l2 in range(L):
                if l1 != l2:
                    d = abs(l1 - l2)
                    # If u has l1 and v has l2, then e has d
                    solver.add_clause([-x(u, l1), -x(v, l2), y(e_idx, d)])
                else:
                    solver.add_clause([-x(u, l1), -x(v, l2)])

    # Symmetry breaking
    # 1. Reverse the whole graph (g -> 2-g)
    # We can just say label of vertex 0 < label of vertex 14?
    # Actually, the graph has automorphisms.
    # The automorphisms are:
    # - Reversing the cliques: clique 0 <-> clique 2
    # - Permuting the indices 0..4 simultaneously in all cliques.

    # Let's fix the first edge to have the maximum difference 40.
    # The difference 40 must be between 0 and 40.
    # So one vertex has 0 and another has 40.
    # Since all vertices in a clique are symmetric, and clique 0 and 2 are symmetric,
    # we can assume the edge with difference 40 is in clique 0, or between clique 0 and 1, or in clique 1.
    # Wait, the edge with difference 40 can be ANY edge.
    # But we can just let the solver find it.

    # Let's just add:
    # V[0] < V[1] < V[2] < V[3] < V[4]
    for i in range(4):
        for l1 in range(L):
            for l2 in range(l1 + 1):
                solver.add_clause([-x(i, l1), -x(i+1, l2)])

    # V[0] < V[14] (to break clique 0 vs clique 2 symmetry)
    # Wait, V[0] is the smallest in clique 0. V[14] is the largest in clique 2? No, V[10..14] are not ordered.
    # Let's just order clique 0.

    print("Solving...")
    start = time.time()
    res = solver.solve()
    print(f"Time: {time.time() - start}")

    if res:
        model = solver.get_model()
        labels = [-1] * V
        for v in range(V):
            for l in range(L):
                if x(v, l) in model:
                    labels[v] = l
        print("SAT")
        print(labels)
    else:
        print("UNSAT")

solve()

